        "total": {
          "type": "number",
          "description": "深睡比例圆环总量。",
          "sampleValue": 100
        },
        "statusText": {
          "type": "string",
          "description": "深睡比例健康状态提示。",
          "sampleValue": "严重偏低"
        }
      },
      "fallAsleepTime": {
        "type": "string",
        "description": "昨晚入睡时间展示文本。",
        "sampleValue": "23:45"
      },
      "wakeUpTime": {
        "type": "string",
        "description": "今日起床时间展示文本。",
        "sampleValue": "06:50"
      },
      "wearableBatteryText": {
        "type": "string",
        "description": "手环电量展示文本。",
        "sampleValue": "43%"
      }
    }
  },
  "assetCandidates": []
}

